// node --test tests/frontend/*.test.mjs
//
// The fixtures are hass stubs generated by tests/test_frontend.py from the
// integration's real entities, one per equipment shape.

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import {
  buildDashboard,
  buildSection,
  buildSections,
  ControlFreakSectionStrategy,
  DEFAULT_TITLES,
  EQUIPMENT_TYPES,
  EMPTY_SECTION,
  sectionOrder,
  shortName,
} from "../../custom_components/controlfreak/frontend/controlfreak-strategy.js";

const fixture = (name) =>
  JSON.parse(readFileSync(new URL(`./fixtures/${name}.json`, import.meta.url), "utf8"));

const headings = (sections) => sections.map((s) => s.cards[0].heading);
const entitiesOf = (section) => section.cards.filter((c) => c.entity).map((c) => c.entity);
const allEntities = (sections) => sections.flatMap(entitiesOf);
const card = (sections, entity) =>
  sections.flatMap((s) => s.cards).find((c) => c.entity === entity);
const featureTypes = (c) => (c.features ?? []).map((f) => f.type);
const CORE_CARDS = new Set(["heading", "tile", "markdown"]);

test("full pool: a section per equipment type, in default order", () => {
  const sections = buildSections(fixture("full-pool"));
  assert.deepEqual(headings(sections), [
    "Pumps",
    "Heating and cooling",
    "Lights and relays",
    "Valves",
    "Temperature and flow",
    "Controller health",
  ]);
});

test("full pool: five pump tiles with speed control, each read-only mode under its pump", () => {
  const hass = fixture("full-pool");
  const pumps = buildSection(hass, "pumps");
  assert.deepEqual(entitiesOf(pumps), [
    "fan.backyard_cleaner_booster",
    "sensor.backyard_cleaner_booster_current_mode",
    "fan.backyard_filter_pump",
    "sensor.backyard_filter_pump_current_mode",
    "fan.backyard_solar_pump",
    "sensor.backyard_solar_pump_current_mode",
    "fan.backyard_spa_jets",
    "sensor.backyard_spa_jets_current_mode",
    "fan.backyard_waterfall",
    "sensor.backyard_waterfall_current_mode",
  ]);
  for (const c of pumps.cards.filter((c) => c.entity?.startsWith("fan."))) {
    assert.deepEqual(featureTypes(c), ["fan-speed"]);
  }
  // The mode is shown, never commanded: no mode-changing feature anywhere.
  assert.deepEqual(featureTypes(card([pumps], "sensor.backyard_spa_jets_current_mode")), []);
  assert.ok(!allEntities([pumps]).some((e) => e.startsWith("select.")));
  // The speed sensor repeats what the pump tile shows.
  assert.ok(!allEntities([pumps]).some((e) => e.endsWith("_speed")));
});

test("mode sensor pairs with the longest matching pump name", () => {
  // "Spa" is a prefix of "Spa Jets": the Spa Jets mode must not go to Spa.
  const hass = structuredClone(fixture("full-pool"));
  const rename = (id, name) => (hass.states[id].attributes.friendly_name = name);
  rename("fan.backyard_waterfall", "Backyard Spa");
  rename("fan.backyard_spa_jets", "Backyard Spa Jets");
  rename("sensor.backyard_spa_jets_current_mode", "Backyard Spa Jets current mode");
  rename("sensor.backyard_waterfall_current_mode", "Backyard Spa current mode");
  const ids = entitiesOf(buildSection(hass, "pumps"));
  const mode = "sensor.backyard_spa_jets_current_mode";
  assert.equal(ids[ids.indexOf("fan.backyard_spa_jets") + 1], mode);
  assert.notEqual(ids[ids.indexOf("fan.backyard_waterfall") + 1], mode);
});

test("pump with preset modes gets the preset-modes feature", () => {
  const hass = structuredClone(fixture("full-pool"));
  const attrs = hass.states["fan.backyard_waterfall"].attributes;
  attrs.supported_features |= 8;
  attrs.preset_modes = ["pool", "spa"];
  assert.deepEqual(featureTypes(card(buildSections(hass), "fan.backyard_waterfall")), [
    "fan-speed",
    "fan-preset-modes",
  ]);
});

test("lights get the effect feature, plain relays a toggle", () => {
  const sections = buildSections(fixture("full-pool"));
  assert.deepEqual(featureTypes(card(sections, "light.backyard_pool_light")), ["light-effect"]);
  assert.deepEqual(featureTypes(card(sections, "switch.backyard_deck_lights")), ["toggle"]);
});

test("heaters and chillers are grouped by role, general relays stay relays", () => {
  const hass = fixture("full-pool");
  assert.deepEqual(entitiesOf(buildSection(hass, "heating")), [
    "switch.backyard_pool_chiller",
    "switch.backyard_spa_heater",
  ]);
  // Deck Lights is a general low-voltage relay: same port family as the
  // heater, different role, so it stays with the relays under its own name.
  assert.deepEqual(entitiesOf(buildSection(hass, "lights")), [
    "switch.backyard_deck_lights",
    "switch.backyard_landscape_lights",
    "light.backyard_pool_light",
    "light.backyard_spa_light",
  ]);
  assert.deepEqual(featureTypes(card(buildSections(hass), "switch.backyard_spa_heater")), [
    "toggle",
  ]);
});

test("a pressure entity, once the integration has one, joins temperature and flow", () => {
  const hass = structuredClone(fixture("full-pool"));
  hass.entities["sensor.backyard_filter_pressure"] = {
    entity_id: "sensor.backyard_filter_pressure",
    platform: "controlfreak",
    translation_key: "pressure",
    labels: [],
  };
  hass.states["sensor.backyard_filter_pressure"] = { state: "12", attributes: {} };
  const ids = entitiesOf(buildSection(hass, "sensors"));
  assert.ok(ids.includes("sensor.backyard_filter_pressure"));
});

test("read-only valve: no toggle anywhere, icon tap opens more-info", () => {
  const sections = buildSections(fixture("valves-skimmers"));
  const valves = sections.find((s) => s.cards[0].heading === "Valves");
  assert.equal(entitiesOf(valves).length, 4);
  for (const c of valves.cards.slice(1)) {
    assert.equal(c.features, undefined);
    assert.deepEqual(c.icon_tap_action, { action: "more-info" });
  }
});

test("a native valve entity gets open/close", () => {
  const hass = structuredClone(fixture("valves-skimmers"));
  hass.entities["valve.backyard_new_valve"] = {
    entity_id: "valve.backyard_new_valve",
    platform: "controlfreak",
    translation_key: "valve",
    labels: [],
  };
  hass.states["valve.backyard_new_valve"] = { state: "closed", attributes: {} };
  assert.deepEqual(featureTypes(card(buildSections(hass), "valve.backyard_new_valve")), [
    "valve-open-close",
  ]);
});

test("lighting-only panel: no pump, valve or sensor sections", () => {
  const sections = buildSections(fixture("lighting-only"));
  assert.deepEqual(headings(sections), ["Lights and relays", "Controller health"]);
  assert.equal(entitiesOf(sections[0]).length, 5);
});

test("valves and skimmers: valves plus a flow tile", () => {
  const sections = buildSections(fixture("valves-skimmers"));
  assert.deepEqual(headings(sections), ["Valves", "Temperature and flow", "Controller health"]);
  assert.deepEqual(entitiesOf(sections[1]), ["binary_sensor.backyard_skimmer_flow"]);
});

test("temperatures get a trend graph", () => {
  const sections = buildSections(fixture("full-pool"));
  assert.deepEqual(featureTypes(card(sections, "sensor.backyard_pool_water")), ["trend-graph"]);
});

test("controller health: connectivity, freeze protection, CPU, firmware", () => {
  const section = buildSection(fixture("full-pool"), "controller");
  assert.deepEqual(entitiesOf(section), [
    "binary_sensor.backyard_controller",
    "sensor.backyard_freeze_protection",
    "sensor.backyard_cpu_temperature",
    "sensor.backyard_firmware_version",
  ]);
});

test("every Control Freak entity is placed exactly once or deliberately folded", () => {
  for (const name of ["full-pool", "lighting-only", "valves-skimmers"]) {
    const hass = fixture(name);
    const shown = allEntities(buildSections(hass));
    assert.equal(new Set(shown).size, shown.length, `${name}: duplicate tile`);
    const ours = Object.values(hass.entities).filter((e) => e.platform === "controlfreak");
    for (const e of ours) {
      const folded = e.translation_key === "pump_speed"; // shown on the pump tile
      assert.equal(shown.includes(e.entity_id), !folded, `${name}: ${e.entity_id}`);
    }
    assert.ok(!shown.includes("sun.sun"), "foreign entity leaked in");
  }
});

test("an unknown future entity lands in Other equipment, never dropped", () => {
  const hass = structuredClone(fixture("lighting-only"));
  hass.entities["sensor.backyard_chlorinator"] = {
    entity_id: "sensor.backyard_chlorinator",
    platform: "controlfreak",
    translation_key: "salt_level",
    labels: [],
  };
  hass.states["sensor.backyard_chlorinator"] = { state: "3200", attributes: {} };
  const sections = buildSections(hass);
  assert.equal(headings(sections).at(-1), "Other equipment");
  assert.deepEqual(entitiesOf(sections.at(-1)), ["sensor.backyard_chlorinator"]);
});

test("hidden entities and entities without state are skipped", () => {
  const hass = structuredClone(fixture("lighting-only"));
  hass.entities["light.backyard_pool_light"].hidden = true;
  delete hass.states["light.backyard_spa_light"];
  const shown = allEntities(buildSections(hass));
  assert.ok(!shown.includes("light.backyard_pool_light"));
  assert.ok(!shown.includes("light.backyard_spa_light"));
});

test("empty: no sections, the dashboard shows a hint instead", () => {
  const hass = fixture("empty");
  assert.deepEqual(buildSections(hass), []);
  const dash = buildDashboard(hass);
  assert.deepEqual(dash.views[0].sections, [EMPTY_SECTION]);
});

test("options: hide, order and per-type titles", () => {
  const hass = fixture("full-pool");
  const sections = buildSections(hass, {
    hide: ["controller", "valves"],
    order: ["sensors", "pumps"],
    titles: { pumps: "Circulation" },
  });
  assert.deepEqual(headings(sections), [
    "Temperature and flow",
    "Circulation",
    "Heating and cooling",
    "Lights and relays",
  ]);
});

test("order ignores unknown and duplicate types", () => {
  assert.deepEqual(sectionOrder({ order: ["bogus", "lights", "lights"] }), [
    "lights",
    ...EQUIPMENT_TYPES.filter((t) => t !== "lights"),
  ]);
});

test("device_id limits the dashboard to one panel", () => {
  const hass = fixture("full-pool");
  assert.deepEqual(buildSections(hass, { device_id: "some-other-panel" }), []);
  assert.equal(buildSections(hass, { device_id: "controlfreak-device" }).length, 6);
});

test("dashboard: one sections view, only core cards", () => {
  const dash = buildDashboard(fixture("full-pool"), { title: "Backyard pool" });
  assert.equal(dash.title, "Backyard pool");
  assert.equal(dash.views.length, 1);
  assert.equal(dash.views[0].type, "sections");
  const types = dash.views[0].sections.flatMap((s) => s.cards.map((c) => c.type));
  for (const t of types) assert.ok(CORE_CARDS.has(t), t);
});

test("section strategy: one block with an optional title", async () => {
  const hass = fixture("full-pool");
  const section = await ControlFreakSectionStrategy.generate(
    { type: "custom:controlfreak", equipment: "lights", title: "Lighting" },
    hass
  );
  assert.equal(section.cards[0].heading, "Lighting");
  assert.equal(entitiesOf(section).length, 4); // two lights, two general relays
});

test("section strategy: missing equipment, unknown type and nothing found", async () => {
  const hass = fixture("lighting-only");
  await assert.rejects(
    ControlFreakSectionStrategy.generate({ type: "custom:controlfreak" }, hass),
    /Set "equipment"/
  );
  await assert.rejects(
    ControlFreakSectionStrategy.generate({ equipment: "spaceships" }, hass),
    /Unknown Control Freak equipment type/
  );
  const none = await ControlFreakSectionStrategy.generate({ equipment: "pumps" }, hass);
  assert.equal(none.cards[0].type, "markdown");
});

test("tile names drop the device name prefix, never shown truncated to it", () => {
  // Live HA 2026.9.3: the device is "Control Freak Automated Pool System" and every
  // tile read "Control Freak ..." because the prefix filled the whole name.
  const hass = fixture("full-pool");
  const tiles = buildSections(hass).flatMap((s) => s.cards).filter((c) => c.entity);
  assert.ok(tiles.length > 10);
  for (const c of tiles) {
    assert.ok(c.name, `${c.entity}: no name`);
    assert.ok(!c.name.startsWith("Backyard"), `${c.entity}: ${c.name}`);
  }
  assert.equal(card(buildSections(hass), "light.backyard_pool_light").name, "Pool Light");
});

test("short name honours a user-renamed device and leaves other names alone", () => {
  const hass = structuredClone(fixture("full-pool"));
  const id = "light.backyard_pool_light";
  assert.equal(shortName(hass, id), "Pool Light");
  hass.devices["controlfreak-device"].name_by_user = "Pool";
  hass.states[id].attributes.friendly_name = "Pool Pool Light";
  assert.equal(shortName(hass, id), "Pool Light");
  hass.states[id].attributes.friendly_name = "My lamp"; // renamed entity, no prefix
  assert.equal(shortName(hass, id), "My lamp");
  hass.states[id].attributes.friendly_name = "Pool"; // name equals the device name
  assert.equal(shortName(hass, id), "Pool");
  delete hass.devices;
  assert.equal(shortName(hass, id), "Pool");
});

test("every type has a default title", () => {
  for (const t of EQUIPMENT_TYPES) assert.ok(DEFAULT_TITLES[t]);
});
